// ============================================================================
// V Spark 2026 - Windows PC Exam-Lock Batch Script Generator
// Generates self-elevating, self-cleaning, network-locking .bat script for student PCs
// Enforces 100% strict lockdown: ONLY V Spark Arena allowed, everything else blocked
// ============================================================================

function generateExamLockScript({ passKey, teamName, university, serverUrl, arenaName }) {
  const cleanTeamName = (teamName || 'Team').replace(/[^a-zA-Z0-9 _-]/g, '');
  const cleanPassKey = (passKey || '').replace(/[^a-zA-Z0-9_-]/g, '');
  const cleanUniversity = (university || 'University').replace(/[^a-zA-Z0-9 _-]/g, '');
  const cleanServerUrl = serverUrl.replace(/\/+$/, '');
  const cleanArenaName = (arenaName || 'V Spark 2026').replace(/[^a-zA-Z0-9 _-]/g, '');

  const batTemplate = [
    '@echo off',
    'setlocal EnableDelayedExpansion',
    'title ' + cleanArenaName + ' - Strict Exam Mode Security Tool',
    '',
    ':: =========================================================================',
    ':: ' + cleanArenaName.toUpperCase() + ' - ARENA STRICT EXAM MODE NETWORK LOCK',
    ':: Team: ' + cleanTeamName,
    ':: University: ' + cleanUniversity,
    ':: =========================================================================',
    '',
    ':: 1. Self-Elevation Check (Run as Administrator)',
    'net session >nul 2>&1',
    'if %errorLevel% neq 0 (',
    '    echo ========================================================',
    '    echo   [' + cleanArenaName.toUpperCase() + '] EXAM MODE SECURITY CHECK',
    '    echo   Administrator privileges required to lock network.',
    '    echo   Prompting Windows for administrator permission...',
    '    echo ========================================================',
    '    powershell -NoProfile -Command "Start-Process cmd -ArgumentList \'/c \\"\\"%~f0\\"\\"\' -Verb RunAs"',
    '    exit /b',
    ')',
    '',
    ':: 2. Configuration Parameters',
    'set "PASS_KEY=' + cleanPassKey + '"',
    'set "SERVER_URL=' + cleanServerUrl + '"',
    'set "APP_DIR=%LOCALAPPDATA%\\VSpark"',
    'set "HOSTS_FILE=%SystemRoot%\\System32\\drivers\\etc\\hosts"',
    'set "HOSTS_BAK=%APP_DIR%\\hosts.vspark.bak"',
    'set "UNLOCK_PATH=%APP_DIR%\\Emergency_Unlock.bat"',
    'set "DESKTOP_UNLOCK=%USERPROFILE%\\Desktop\\Emergency_Unlock.bat"',
    'set "LOCK_SCRIPT_PATH=%~f0"',
    '',
    'if not exist "%APP_DIR%" mkdir "%APP_DIR%" >nul 2>&1',
    'echo %LOCK_SCRIPT_PATH% > "%APP_DIR%\\script.path"',
    '',
    ':: 3. Backup Original Hosts File (Preserve system configuration)',
    'if not exist "%HOSTS_BAK%" (',
    '    copy /y "%HOSTS_FILE%" "%HOSTS_BAK%" >nul 2>&1',
    ')',
    '',
    ':: 4. Strict Blocklist: Redirect AI, Search, Cheating & Social Platforms to Localhost',
    '(',
    '    echo.',
    '    echo # --- V SPARK 2026 STRICT EXAM LOCK BLOCKLIST ---',
    '    echo 127.0.0.1 chatgpt.com chat.openai.com api.openai.com auth0.openai.com',
    '    echo 127.0.0.1 claude.ai anthropic.com api.anthropic.com',
    '    echo 127.0.0.1 gemini.google.com aistudio.google.com deepseek.com www.deepseek.com',
    '    echo 127.0.0.1 copilot.microsoft.com perplexity.ai poe.com blackbox.ai phind.com',
    '    echo 127.0.0.1 google.com www.google.com bing.com www.bing.com duckduckgo.com',
    '    echo 127.0.0.1 github.com www.github.com gist.github.com gitlab.com',
    '    echo 127.0.0.1 stackoverflow.com stackexchange.com leetcode.com geeksforgeeks.org',
    '    echo 127.0.0.1 hackerrank.com codeforces.com codepen.io replit.com programiz.com w3schools.com',
    '    echo 127.0.0.1 web.whatsapp.com whatsapp.com discord.com web.telegram.org telegram.org',
    '    echo 127.0.0.1 youtube.com www.youtube.com facebook.com instagram.com reddit.com twitter.com x.com',
    ') >> "%HOSTS_FILE%"',
    'ipconfig /flushdns >nul 2>&1',
    '',
    ':: 5. Generate Hidden Emergency Unlocker (For Faculty / Emergency Use)',
    '(',
    '  echo @echo off',
    '  echo setlocal EnableDelayedExpansion',
    '  echo net session ^>nul 2^>^&1',
    '  echo if %%errorLevel%% neq 0 (',
    '  echo   powershell -NoProfile -Command "Start-Process cmd -ArgumentList \'/c \\"\\"%%~f0\\"\\"\' -Verb RunAs"',
    '  echo   exit /b',
    '  echo ^)',
    '  echo ========================================================',
    '  echo   [' + cleanArenaName.toUpperCase() + '] RESTORING NORMAL INTERNET ACCESS...',
    '  echo ========================================================',
    '  echo.',
    '  echo Stopping background watchdog process...',
    '  echo type nul ^> "%LOCALAPPDATA%\\VSpark\\unlock.signal" 2^>nul',
    '  echo powershell -NoProfile -Command "Get-CimInstance Win32_Process | Where-Object { $_.CommandLine -like \'*pc-heartbeat*\' } | ForEach-Object { Stop-Process -Id $_.ProcessId -Force -ErrorAction SilentlyContinue }" ^>nul 2^>^&1',
    '  echo Restoring Windows Firewall rules...',
    '  echo netsh advfirewall set allprofiles firewallpolicy blockinbound,allowoutbound ^>nul 2^>^&1',
    '  echo netsh advfirewall firewall delete rule name="VSpark_Allow_DNS" ^>nul 2^>^&1',
    '  echo netsh advfirewall firewall delete rule name="VSpark_Allow_DNS_TCP" ^>nul 2^>^&1',
    '  echo netsh advfirewall firewall delete rule name="VSpark_Allow_DHCP" ^>nul 2^>^&1',
    '  echo netsh advfirewall firewall delete rule name="VSpark_Allow_Loopback" ^>nul 2^>^&1',
    '  echo netsh advfirewall firewall delete rule name="VSpark_Allow_Arena" ^>nul 2^>^&1',
    '  echo netsh advfirewall firewall delete rule name="VSpark_Block_Outbound" ^>nul 2^>^&1',
    '  echo Restoring hosts configuration...',
    '  echo if exist "%LOCALAPPDATA%\\VSpark\\hosts.vspark.bak" copy /y "%LOCALAPPDATA%\\VSpark\\hosts.vspark.bak" "%SystemRoot%\\System32\\drivers\\etc\\hosts" ^>nul 2^>^&1',
    '  echo ipconfig /flushdns ^>nul 2^>^&1',
    '  echo Notifying server...',
    '  echo powershell -NoProfile -Command "try { Invoke-RestMethod -Uri \'' + cleanServerUrl + '/api/team/pc-lock\' -Method Post -Body \'{\\"passKey\\":\\"' + cleanPassKey + '\\",\\"status\\":\\"unlocked\\"}\' -ContentType \'application/json\' -TimeoutSec 5 } catch {}" ^>nul 2^>^&1',
    '  echo.',
    '  echo Cleaning up lock script and temporary files...',
    '  echo if exist "%LOCALAPPDATA%\\VSpark\\script.path" (',
    '  echo   set /p ORIG_SCRIPT=^<"%LOCALAPPDATA%\\VSpark\\script.path"',
    '  echo   if exist "!ORIG_SCRIPT!" del /f /q "!ORIG_SCRIPT!" ^>nul 2^>^&1',
    '  echo )',
    '  echo del /f /q "%USERPROFILE%\\Desktop\\Emergency_Unlock.bat" ^>nul 2^>^&1',
    '  echo rd /s /q "%LOCALAPPDATA%\\VSpark" ^>nul 2^>^&1',
    '  echo.',
    '  echo ========================================================',
    '  echo   [SUCCESS] Internet 100%% Restored!',
    '  echo   Exam lock script terminated and removed from PC.',
    '  echo ========================================================',
    '  echo timeout /t 4 ^>nul 2^>^&1',
    ') > "%UNLOCK_PATH%"',
    'copy /y "%UNLOCK_PATH%" "%DESKTOP_UNLOCK%" >nul 2>&1',
    '',
    ':: 6. Apply Windows Firewall Lockdown via PowerShell',
    'echo [V Spark] Locking network and confirming security with Arena server...',
    'powershell -NoProfile -ExecutionPolicy Bypass -Command "& { try { Invoke-RestMethod -Uri \'' + cleanServerUrl + '/api/team/pc-lock\' -Method Post -Body (@{ passKey = \'' + cleanPassKey + '\'; status = \'locked\' } | ConvertTo-Json) -ContentType \'application/json\' -TimeoutSec 10 | Out-Null; } catch {}; try { $ips = @(\'216.24.57.0/24\'); try { $ips += [System.Net.Dns]::GetHostAddresses(([Uri]\'' + cleanServerUrl + '\').Host) | ForEach-Object { $_.IPAddressToString } } catch {}; $cdns = @(\'cdn.tailwindcss.com\',\'cdnjs.cloudflare.com\',\'cdn.sheetjs.com\',\'fonts.googleapis.com\',\'fonts.gstatic.com\'); foreach ($d in $cdns) { try { $ips += [System.Net.Dns]::GetHostAddresses($d) | ForEach-Object { $_.IPAddressToString } } catch {} }; $uIps = ($ips | Where-Object { $_ -notlike \'*:\*\' } | Sort-Object -Unique) -join \',\'; netsh advfirewall firewall add rule name=\'VSpark_Allow_DNS\' dir=out action=allow protocol=UDP remoteport=53 | Out-Null; netsh advfirewall firewall add rule name=\'VSpark_Allow_DNS_TCP\' dir=out action=allow protocol=TCP remoteport=53 | Out-Null; netsh advfirewall firewall add rule name=\'VSpark_Allow_DHCP\' dir=out action=allow protocol=UDP remoteport=67,68 | Out-Null; netsh advfirewall firewall add rule name=\'VSpark_Allow_Loopback\' dir=out action=allow remoteip=127.0.0.1 protocol=TCP | Out-Null; if ($uIps) { netsh advfirewall firewall add rule name=\'VSpark_Allow_Arena\' dir=out action=allow remoteip=$uIps protocol=TCP remoteport=80,443 | Out-Null }; netsh advfirewall set allprofiles firewallpolicy blockinbound,blockoutbound | Out-Null; try { Invoke-RestMethod -Uri \'' + cleanServerUrl + '/api/team/pc-lock\' -Method Post -Body (@{ passKey = \'' + cleanPassKey + '\'; status = \'locked\' } | ConvertTo-Json) -ContentType \'application/json\' -TimeoutSec 8 | Out-Null; } catch {}; } catch {} }"',
    '',
    'echo.',
    'echo ========================================================',
    'echo   [SUCCESS] Strict PC Lock Active!',
    'echo   Only ' + cleanArenaName + ' website is accessible.',
    'echo   All external websites, search engines and AI tools are blocked.',
    'echo   This window will now run silently in the background.',
    'echo ========================================================',
    'timeout /t 3 >nul 2>&1',
    '',
    ':: 7. Launch Background Watchdog and Exit Visible Console',
    'powershell -WindowStyle Hidden -NoProfile -ExecutionPolicy Bypass -Command "& { Add-Type -AssemblyName System.Windows.Forms; $pKey = \'' + cleanPassKey + '\'; $sUrl = \'' + cleanServerUrl + '\'; $self = \'%~f0\'; $running = $true; $reason = \'Contest Finished\'; try { Invoke-RestMethod -Uri \\"$sUrl/api/team/pc-heartbeat\\" -Method Post -Body (@{ passKey = $pKey } | ConvertTo-Json) -ContentType \'application/json\' -TimeoutSec 6 | Out-Null; } catch {}; while ($running) { Start-Sleep -Seconds 3; if (Test-Path \\"$env:LOCALAPPDATA\\VSpark\\unlock.signal\\") { $reason = \'Emergency Unlock Activated\'; $running = $false; break; }; try { $body = @{ passKey = $pKey } | ConvertTo-Json; $res = Invoke-RestMethod -Uri \\"$sUrl/api/team/pc-heartbeat\\" -Method Post -Body $body -ContentType \'application/json\' -TimeoutSec 6; if ($res.success) { if ($res.shouldUnlock -eq $true -or $res.isCompleted -eq $true -or $res.allSolved -eq $true -or $res.leftArena -eq $true -or $res.teamStatus -eq \'left_early\' -or $res.contestStatus -eq \'ended\' -or ($res.remainingSeconds -ne $null -and $res.remainingSeconds -le 0)) { $reason = if ($res.unlockReason) { $res.unlockReason } elseif ($res.leftArena -eq $true -or $res.teamStatus -eq \'left_early\') { \'You Left the Contest (Session Closed)\' } elseif ($res.isCompleted -eq $true -or $res.allSolved -eq $true) { \'All Challenges Completed! Congratulations!\' } else { \'Contest Time Up (Timer Ended)\' }; $running = $false; } } } catch {} }; netsh advfirewall set allprofiles firewallpolicy blockinbound,allowoutbound | Out-Null; netsh advfirewall firewall delete rule name=\'VSpark_Allow_DNS\' | Out-Null; netsh advfirewall firewall delete rule name=\'VSpark_Allow_DNS_TCP\' | Out-Null; netsh advfirewall firewall delete rule name=\'VSpark_Allow_DHCP\' | Out-Null; netsh advfirewall firewall delete rule name=\'VSpark_Allow_Loopback\' | Out-Null; netsh advfirewall firewall delete rule name=\'VSpark_Allow_Arena\' | Out-Null; netsh advfirewall firewall delete rule name=\'VSpark_Block_Outbound\' | Out-Null; $hBak = \\"$env:LOCALAPPDATA\\VSpark\\hosts.vspark.bak\\"; $hDst = \\"$env:SystemRoot\\System32\\drivers\\etc\\hosts\\"; if (Test-Path $hBak) { Copy-Item -Path $hBak -Destination $hDst -Force -ErrorAction SilentlyContinue; ipconfig /flushdns | Out-Null; }; try { $unBody = @{ passKey = $pKey; status = \'unlocked\' } | ConvertTo-Json; Invoke-RestMethod -Uri \\"$sUrl/api/team/pc-lock\\" -Method Post -Body $unBody -ContentType \'application/json\' -TimeoutSec 6 | Out-Null; } catch {}; [System.Windows.Forms.MessageBox]::Show(\\"🎉 ' + cleanArenaName + ': $reason`n`nInternet access has been 100% restored and the exam lock tool has been removed from your PC.\\", \'' + cleanArenaName + ' Strict Exam Mode\', [System.Windows.Forms.MessageBoxButtons]::OK, [System.Windows.Forms.MessageBoxIcon]::Information); try { Remove-Item \\"$env:USERPROFILE\\Desktop\\Emergency_Unlock.bat\\" -Force -ErrorAction SilentlyContinue; Remove-Item \\"$env:LOCALAPPDATA\\VSpark\\Emergency_Unlock.bat\\" -Force -ErrorAction SilentlyContinue; Remove-Item \\"$env:LOCALAPPDATA\\VSpark\\" -Force -Recurse -ErrorAction SilentlyContinue; Remove-Item $self -Force -ErrorAction SilentlyContinue; } catch {} }"',
    '',
    'exit /b'
  ];

  return batTemplate.join('\r\n');
}

module.exports = { generateExamLockScript };
